var orders = new List<Order>
{
    new("Sara", "Books", 40m), new("Omar", "Tech", 300m),
    new("Sara", "Tech", 120m), new("Lina", "Books", 60m),
};

// GroupBy: total per customer, biggest first
var totals = orders
    .GroupBy(o => o.Customer)
    .Select(g => new { Customer = g.Key, Total = g.Sum(o => o.Amount), Count = g.Count() })
    .OrderByDescending(x => x.Total);

foreach (var t in totals)
    Console.WriteLine($"{t.Customer}: {t.Total} ({t.Count} orders)");

// Query syntax: the same thing, SQL-like (less common in modern code)
var books = from o in orders where o.Category == "Books" orderby o.Amount select o.Customer;
Console.WriteLine(string.Join(", ", books));

record Order(string Customer, string Category, decimal Amount);

